/**
 * @summary Bulk upload players from CSV
 */
export const getBulkUploadPlayersUrl = () => {
  return `/api/player/bulk-upload`;
};

export const bulkUploadPlayers = async (
  bulkUploadPlayersBody: BulkUploadPlayersBody,
  options?: RequestInit,
): Promise<BulkUploadResponse> => {
  const formData = new FormData();
  if (bulkUploadPlayersBody.file !== undefined) {
    formData.append(`file`, bulkUploadPlayersBody.file);
  }
  if (bulkUploadPlayersBody.auctionId !== undefined) {
    formData.append(`auctionId`, bulkUploadPlayersBody.auctionId);
  }
  if (bulkUploadPlayersBody.basePrice !== undefined) {
    formData.append(`basePrice`, bulkUploadPlayersBody.basePrice.toString());
  }

  return customFetch<BulkUploadResponse>(getBulkUploadPlayersUrl(), {
    ...options,
    method: "POST",
    body: formData,
  });
};

